        (1,.5)coordinate (H)
        +(-8:3)coordinate (C)
        ($(B)!0.65!(C)$)coordinate (E)
        ($(A)!0.65!(C)$)coordinate (F)
        ;
        %           \pgfresetboundingbox
        \clip (0,0)rectangle(5,\cao);
        \fill[lime!70!olive](0,0)rectangle(5,\cao);
        \pgfmathsetseed{14159}
        \draw[decorate, decoration={snake,post length=0.5 mm,random steps, segment length=3mm, amplitude=3pt}, lime!70!black, line width=.5mm, double=cyan!60!white, double distance=2cm](0,2.5)--(5,2.5);
        \draw (B)--(C)--(A);
        \draw[dashed] (A)--(B) (E)--(F);
        \foreach \p/\g/\pp in{
            A/-120/A,
            B/150/B,
            C/20/C,
            E/20/E,
            F/-130/F
        } \shade[shading=ball,fill=cyan](\p)circle(1.5pt)node[shift={(\g:.35)}]{$\pp$};
        \path (H)--(C);
        \end{tikzpicture}
}
