        \draw[dashed] (A)--(B) (E)--(F);
        \foreach \p/\g/\pp in{
            A/-120/A,
            B/150/B,
            C/20/C,
            E/20/E,
            F/-130/F
        } \shade[shading=ball,fill=cyan](\p)circle(1.5pt)node[shift={(\g:.35)}]{$\pp$};
